package com.example.platform.studio.camera;
import com.example.platform.studio.serialization.CanonicalJson;
import java.util.Map;
public sealed interface CameraPose permits CameraPose.TransformPose,CameraPose.LookAtPose{String canonicalJson();
record TransformPose(Transform transform)implements CameraPose{public TransformPose{if(transform==null)throw new IllegalArgumentException("transform required");}public String canonicalJson(){return CanonicalJson.object(Map.of("transform",transform.canonicalJson(),"type",CanonicalJson.quote("TRANSFORM")));}}
record LookAtPose(Vector3 positionMeters,Vector3 targetMeters,Vector3 up)implements CameraPose{public LookAtPose{if(positionMeters==null||targetMeters==null||up==null||positionMeters.equals(targetMeters))throw new IllegalArgumentException("valid look-at pose required");if(up.equals(Vector3.ZERO))throw new IllegalArgumentException("look-at up vector must be non-zero");var dx=targetMeters.x().value().subtract(positionMeters.x().value());var dy=targetMeters.y().value().subtract(positionMeters.y().value());var dz=targetMeters.z().value().subtract(positionMeters.z().value());var cx=dy.multiply(up.z().value()).subtract(dz.multiply(up.y().value()));var cy=dz.multiply(up.x().value()).subtract(dx.multiply(up.z().value()));var cz=dx.multiply(up.y().value()).subtract(dy.multiply(up.x().value()));if(cx.signum()==0&&cy.signum()==0&&cz.signum()==0)throw new IllegalArgumentException("look-at up vector cannot be collinear with target direction");}public String canonicalJson(){return CanonicalJson.object(Map.of("positionMeters",positionMeters.canonicalJson(),"targetMeters",targetMeters.canonicalJson(),"type",CanonicalJson.quote("LOOK_AT"),"up",up.canonicalJson()));}}
}
